mapper.select:
SELECT t.template_id AS templateId, t.title, t.category, t.description, t.prompt, t.cover_file_id AS coverFileId, f.object_key AS coverUrl, t.sort_order AS sortOrder, t.use_count AS useCount, t.status, t.create_time AS createTime, t.update_time AS updateTime FROM viz_template t LEFT JOIN viz_file f ON f.file_id = t.cover_file_id WHERE t.deleted = 0 AND t.category = #{category} AND t.status = #{status}
AND (t.title LIKE CONCAT('%', #{keyword}, '%') OR t.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sort_order ASC, template_id DESC

mapper.update:
UPDATE viz_template SET deleted = 1, update_time = NOW()
WHERE template_id IN
#{id}

UPDATE viz_creation_task SET status = #{status}, progress = COALESCE(#{progress}, progress),
    work_id = COALESCE(#{workId}, work_id), failure_reason = #{failureReason}, update_time = NOW()
WHERE task_id = #{taskId}

mapper.select:
SELECT user_id AS userId, balance, total_granted AS totalGranted,
       total_consumed AS totalConsumed, update_time AS updateTime
FROM viz_credit_account WHERE user_id = #{userId}

SELECT record_id AS recordId, record_type AS recordType, amount, biz_type AS bizType,
       biz_id AS bizId, title, detail, create_time AS createTime
FROM viz_credit_record WHERE user_id = #{userId}
AND record_type = #{type}
ORDER BY record_id DESC
